use std::fs;
use std::io::{self, Read, Write};
use std::path::PathBuf;
use std::process::ExitCode;

use clap::Parser;
use regex::{NoExpand, Regex, RegexBuilder};

#[derive(Parser, Debug)]
#[command(
    name = "sd",
    version = "1.0.0",
    about = "An intuitive find & replace CLI"
)]
struct Cli {
    /// Display changes in a human reviewable format (the specifics of the format are likely to
    /// change in the future)
    #[arg(short, long)]
    preview: bool,

    /// Treat FIND and REPLACE_WITH args as literal strings
    #[arg(short = 'F', long = "fixed-strings")]
    fixed_strings: bool,

    /// Limit the number of replacements that can occur per file. 0 indicates unlimited
    #[arg(short = 'n', long = "max-replacements", default_value_t = 0)]
    max_replacements: usize,

    /// Regex flags. May be combined (like `-f mc`).
    ///
    /// c - case-sensitive
    ///
    /// e - disable multi-line matching
    ///
    /// i - case-insensitive
    ///
    /// m - multi-line matching
    ///
    /// s - make `.` match newlines
    ///
    /// w - match full words only
    #[arg(short, long)]
    flags: Option<String>,

    /// The regexp or string (if using `-F`) to search for
    find: String,

    /// What to replace each match with. Unless in string mode, you may use captured values like
    /// $1, $2, etc
    replace_with: String,

    /// The path to file(s). This is optional - sd can also read from STDIN.
    ///
    /// Note: sd modifies files in-place by default. See documentation for examples.
    files: Vec<PathBuf>,
}

fn main() -> ExitCode {
    let cli = Cli::parse();

    match run(cli) {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("error: {err}");
            ExitCode::from(1)
        }
    }
}

fn run(cli: Cli) -> Result<(), String> {
    let regex = build_regex(&cli.find, cli.fixed_strings, cli.flags.as_deref())?;

    if cli.files.is_empty() {
        let input = read_stdin().map_err(|err| err.to_string())?;
        let output = replace_all(&regex, &input, &cli.replace_with, cli.fixed_strings, cli.max_replacements);
        write_stdout(&output).map_err(|err| err.to_string())?;
        return Ok(());
    }

    let mut loaded_files = Vec::with_capacity(cli.files.len());
    for path in &cli.files {
        if !path.exists() {
            return Err(format!("invalid path: {}", path.display()));
        }

        let content = fs::read_to_string(path).map_err(|err| err.to_string())?;
        loaded_files.push((path, content));
    }

    let outputs: Vec<(&PathBuf, String)> = loaded_files
        .iter()
        .map(|(path, content)| {
            (
                *path,
                replace_all(
                    &regex,
                    content,
                    &cli.replace_with,
                    cli.fixed_strings,
                    cli.max_replacements,
                ),
            )
        })
        .collect();

    if cli.preview {
        let mut stdout = io::stdout().lock();
        if outputs.len() == 1 {
            stdout
                .write_all(outputs[0].1.as_bytes())
                .map_err(|err| err.to_string())?;
            return Ok(());
        }

        for (path, output) in outputs {
            write!(stdout, "----- FILE {} -----\n", path.display()).map_err(|err| err.to_string())?;
            stdout
                .write_all(output.as_bytes())
                .map_err(|err| err.to_string())?;
        }
        return Ok(());
    }

    for (path, output) in outputs {
        fs::write(path, output).map_err(|err| err.to_string())?;
    }

    Ok(())
}

fn build_regex(find: &str, fixed_strings: bool, flags: Option<&str>) -> Result<Regex, String> {
    let flags = flags.unwrap_or_default();
    let mut pattern = if fixed_strings {
        regex::escape(find)
    } else {
        find.to_owned()
    };

    if flags.chars().any(|flag| flag == 'w') {
        pattern = format!(r"\b(?:{pattern})\b");
    }

    let mut builder = RegexBuilder::new(&pattern);
    builder.multi_line(true);

    for flag in flags.chars() {
        match flag {
            'c' => {
                builder.case_insensitive(false);
            }
            'i' => {
                builder.case_insensitive(true);
            }
            's' => {
                builder.dot_matches_new_line(true);
            }
            _ => {}
        }
    }

    if flags.chars().any(|flag| flag == 'e') {
        builder.multi_line(false);
    } else if flags.chars().any(|flag| flag == 'm') {
        builder.multi_line(true);
    }

    builder
        .build()
        .map_err(|err| format!("invalid regex {err}"))
}

fn replace_all(
    regex: &Regex,
    input: &str,
    replace_with: &str,
    fixed_strings: bool,
    max_replacements: usize,
) -> String {
    if fixed_strings {
        if max_replacements == 0 {
            regex.replace_all(input, NoExpand(replace_with)).into_owned()
        } else {
            regex
                .replacen(input, max_replacements, NoExpand(replace_with))
                .into_owned()
        }
    } else if max_replacements == 0 {
        regex.replace_all(input, replace_with).into_owned()
    } else {
        regex
            .replacen(input, max_replacements, replace_with)
            .into_owned()
    }
}

fn read_stdin() -> io::Result<String> {
    let mut input = String::new();
    io::stdin().lock().read_to_string(&mut input)?;
    Ok(input)
}

fn write_stdout(output: &str) -> io::Result<()> {
    io::stdout().lock().write_all(output.as_bytes())
}

