+}
+
+func parseArgs(args []string, binName string) (options, action, *cliError) {
+	var opts options
+
+	var previewSet bool
+	var fixedStringsSet bool
+	var maxReplacementsSet bool
+	var flagsSet bool
+	var positional []string
+	parsingFlags := true
+
+	for i := 0; i < len(args); i++ {
+		arg := args[i]
