+	return &cliError{
+		message: fmt.Sprintf("the argument '%s' cannot be used multiple times", name),
+		usage:   "[OPTIONS] <FIND> <REPLACE_WITH> [FILES]...",
+	}
+}
+
+func missingValueError(name string) *cliError {
+	return &cliError{
+		message: fmt.Sprintf("a value is required for '%s' but none was supplied", name),
+	}
+}
+
+func invalidValueError(name, value string) *cliError {
+	return &cliError{
+		message: fmt.Sprintf("invalid value '%s' for '%s': invalid digit found in string", value, name),
+	}
+}
