		index, err := strconv.Atoi(name)
		if err != nil {
			return dst
		}
		return appendMatchByIndex(dst, index, src, match)
	}

	for idx, candidate := range names {
		if candidate == name {
			return appendMatchByIndex(dst, idx, src, match)
		}
	}

	return dst
}

func isAllDigits(value string) bool {
	for _, ch := range value {
		if ch < '0' || ch > '9' {
			return false
		}
	}
	return value != ""
}

func appendMatchByIndex(dst []byte, index int, src []byte, match []int) []byte {
	slot := index * 2
	if slot+1 >= len(match) {
		return dst
	}

	start, end := match[slot], match[slot+1]
